// Por convención, las interfaces empiezan con 'I'
public interface IDamageable
{
    void TakeDamage(int amount);  // No tiene cuerpo
    int Health { get; }           // Propiedad sin implementación
}

// Implementar la interface (usa : igual que herencia)
public class Enemy : MonoBehaviour, IDamageable
{
    public int Health { get; private set; } = 100;

    public void TakeDamage(int amount)
    {
        Health -= amount;
        if (Health <= 0) Die();
    }
}

// Una clase puede implementar VARIAS interfaces a la vez
public class Player : MonoBehaviour, IDamageable, IInteractable, IMovable
{
    // Debe implementar los métodos de TODAS las interfaces
    public void TakeDamage(int amount) { ... }
    public void Interact() { ... }
    public void Move(Vector3 direction) { ... }
}

// Puedes usar el tipo de la interface como referencia
IDamageable target = GetComponent<IDamageable>();
if (target != null) target.TakeDamage(50);

En Unity es muy común usar interfaces para hacer código genérico. En lugar de hacer <code>GetComponent&lt;Enemy&gt;()</code> (que solo funciona con Enemy), usas <code>GetComponent&lt;IDamageable&gt;()</code> que funciona con <strong>cualquier cosa damageable</strong> — Enemy, Player, BreakableBox, etc:<br><pre>void OnTriggerEnter(Collider other) {
    IDamageable target = other.GetComponent&lt;IDamageable&gt;();
    if (target != null)
        target.TakeDamage(damage);
    // ¡No importa qué tipo de objeto es!
}</pre>

